using System.Text;
using System.Text.Json;
using CatTransform.Application;
using CatTransform.Conversion;
using CatTransform.Core;
using CatTransform.Documents;
using CatTransform.Infrastructure;
using DocumentFormat.OpenXml;
using DocumentFormat.OpenXml.Packaging;
using W=DocumentFormat.OpenXml.Wordprocessing;
using Xunit;
namespace CatTransform.Tests;
public sealed class EngineTests : IDisposable {
 private readonly string dir=Path.Combine(Path.GetTempPath(),"catTransform-tests-"+Guid.NewGuid());
 private readonly TextConverter text=new();
 public EngineTests()=>Directory.CreateDirectory(dir);
 private string FilePath(string name)=>Path.Combine(dir,name);
 private async Task<string> Convert(string ext,string content,Scope? scope=null){var src=FilePath(Guid.NewGuid()+ext);var dst=FilePath(Guid.NewGuid()+ext);await File.WriteAllTextAsync(src,content,new UTF8Encoding(false));await new DocumentConverter(text).ConvertAsync(src,dst,new(){Scope=scope??new()},default);return await File.ReadAllTextAsync(dst);}
 [Theory][InlineData("s2t","汉字","漢字")][InlineData("t2s","漢字","汉字")][InlineData("s2tw","汉字","漢字")][InlineData("s2hk","汉字","漢字")][InlineData("s2twp","软件鼠标网络","軟體滑鼠網路")][InlineData("tw2sp","軟體滑鼠網路","软件鼠标网络")][InlineData("tw2s","漢字","汉字")][InlineData("hk2s","漢字","汉字")]
 public void OpenCc(string config,string input,string expected)=>Assert.Equal(expected,text.Convert(input,new(){Config=config}));
 [Fact]public void ConcurrentEngine(){Parallel.For(0,1000,i=>Assert.Equal(i%2==0?"漢字":"汉字",text.Convert(i%2==0?"汉字":"漢字",new(){Config=i%2==0?"s2t":"t2s"})));}
 [Fact]public void RuleOrderAndProtection(){var options=new ConversionOptions{Rules=[new(){Enabled=true,Kind=RuleKind.Protect,Pattern="软件"},new(){Enabled=true,Pattern="鼠标",Replacement="网络",Stage=RuleStage.Before},new(){Enabled=true,Pattern="網絡",Replacement="结果",Stage=RuleStage.After}]};text.Validate(options);Assert.Equal("软件结果",text.Convert("软件鼠标",options));}
 [Fact]public void ConflictsRejected(){Assert.Throws<ArgumentException>(()=>text.Validate(new(){Rules=[new(){Enabled=true,Pattern="a"},new(){Enabled=true,Pattern="a"}]}));}
 [Fact]public void RegexTimeout(){var options=new ConversionOptions{Rules=[new(){Enabled=true,Kind=RuleKind.Regex,Pattern=@"^(a+)+$",Replacement="",AllowBacktracking=true},new(){Enabled=true,Kind=RuleKind.Regex,Pattern=@"^(a+)\1+$",AllowBacktracking=true,Order=1}]};text.Validate(options);Assert.Throws<System.Text.RegularExpressions.RegexMatchTimeoutException>(()=>text.Convert(new string('a',100000)+"!",options));}
 [Fact]public void RulePackageRejectsDuplicateIds(){var rule=new Rule{Pattern="汉"};Assert.Throws<ArgumentException>(()=>RulePackages.Import(RulePackages.Export([rule]),[rule],false,text));}
 [Fact]public async Task EncodingBomAndNewline(){var source=FilePath("bom.txt");await File.WriteAllTextAsync(source,"汉字\r\n转换\r\n",new UnicodeEncoding(false,true,true));var dst=FilePath("out.txt");await new DocumentConverter(text).ConvertAsync(source,dst,new(),default);var bytes=await File.ReadAllBytesAsync(dst);Assert.Equal(new byte[]{255,254},bytes[..2]);Assert.Equal("漢字\r\n轉換\r\n",Encoding.Unicode.GetString(bytes[2..]));}
 [Fact]public async Task UnknownEncodingFails(){var source=FilePath("gbk.txt");await File.WriteAllBytesAsync(source,[0xba,0xba,0xd7,0xd6]);await Assert.ThrowsAsync<DecoderFallbackException>(()=>EncodedText.ReadAsync(source,default));}
 [Fact]public async Task MarkdownProtectsSyntax(){var result=await Convert(".md","# 汉字\n[汉字](汉字.md) `汉字`\n\n```txt\n汉字\n```\n");Assert.Contains("# 漢字",result);Assert.Contains("[漢字](汉字.md)",result);Assert.Contains("`汉字`",result);Assert.Contains("```txt\n汉字\n```",result);}
 [Fact]public async Task SrtKeepsTiming(){Assert.Equal("1\r\n00:00:01,000 --> 00:00:03,000\r\n漢字\r\n",await Convert(".srt","1\r\n00:00:01,000 --> 00:00:03,000\r\n汉字\r\n"));}
 [Fact]public async Task AssKeepsControlTags(){var source="[Events]\r\nFormat: Layer, Start, End, Style, Text\r\nDialogue: 0,0:00:00.00,0:00:03.00,汉字,{\\pos(1,2)}汉字\\N转换{\\p1}m 0 0 l 1 1{\\p0}汉字";var result=await Convert(".ass",source);Assert.Contains(",汉字,{\\pos(1,2)}漢字\\N轉換{\\p1}m 0 0 l 1 1{\\p0}漢字",result);}
 [Fact]public async Task CsvKeepsHeaderAndMultiline(){var result=await Convert(".csv","汉字,列\r\n\"汉字,转换\",\"汉字\r\n转换\"\r\n");Assert.StartsWith("汉字,列\r\n",result);Assert.Contains("\"漢字,轉換\"",result);Assert.Contains("\"漢字\r\n轉換\"",result);}
 [Fact]public async Task JsonValuesOnly(){using var parsed=JsonDocument.Parse(await Convert(".json","{\"汉字\":\"汉字\",\"n\":1,\"b\":true}"));Assert.Equal("漢字",parsed.RootElement.GetProperty("汉字").GetString());Assert.Equal(1,parsed.RootElement.GetProperty("n").GetInt32());Assert.True(parsed.RootElement.GetProperty("b").GetBoolean());}
 [Fact]public async Task JsonConflictFails()=>await Assert.ThrowsAsync<InvalidDataException>(()=>Convert(".json","{\"发\":1,\"發\":2}",new(){JsonKeys=true}));
 [Fact]public async Task JsonPointerScope(){using var parsed=JsonDocument.Parse(await Convert(".json","{\"a\":\"汉字\",\"b\":\"汉字\"}",new(){JsonPaths=["/b"]}));Assert.Equal("汉字",parsed.RootElement.GetProperty("a").GetString());Assert.Equal("漢字",parsed.RootElement.GetProperty("b").GetString());}
 [Fact]public async Task ConcurrentSafeCommit(){var source=FilePath("汉.txt");await File.WriteAllTextAsync(source,"original");var output=FilePath("output");var results=await Task.WhenAll(Enumerable.Range(0,30).Select(_=>new SafeOutput().WriteAsync(source,"汉.txt",output,p=>File.WriteAllTextAsync(p,"converted"),default)));Assert.Equal(30,results.Distinct().Count());Assert.Equal("original",await File.ReadAllTextAsync(source));Assert.All(results,p=>Assert.Equal("converted",File.ReadAllText(p)));Assert.Empty(Directory.GetFiles(output,"*.tmp*"));}
 [Fact]public async Task CancelDiscardsTemporary(){var source=FilePath("source.txt");await File.WriteAllTextAsync(source,"汉");using var cts=new CancellationTokenSource();var output=FilePath("output");await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>new SafeOutput().WriteAsync(source,"source.txt",output,async p=>{await File.WriteAllTextAsync(p,"漢");cts.Cancel();},cts.Token));Assert.Empty(Directory.GetFiles(output));}
 [Fact]public async Task FailedWriteDiscardsTemporary(){var source=FilePath("source.txt");await File.WriteAllTextAsync(source,"汉");var output=FilePath("output");await Assert.ThrowsAsync<InvalidDataException>(()=>new SafeOutput().WriteAsync(source,"source.txt",output,async p=>{await File.WriteAllTextAsync(p,"bad");throw new InvalidDataException();},default));Assert.Empty(Directory.GetFiles(output));}
 [Fact]public async Task RejectTraversal(){await Assert.ThrowsAsync<IOException>(()=>new SafeOutput().WriteAsync(FilePath("source.txt"),"../escape.txt",FilePath("output"),p=>File.WriteAllTextAsync(p,"x"),default));}
 [Fact]public async Task OutputBesideSourceGetsNumber(){var source=FilePath("source.txt");await File.WriteAllTextAsync(source,"原文");var result=await new SafeOutput().WriteAsync(source,"source.txt",dir,p=>File.WriteAllTextAsync(p,"新文"),default);Assert.Equal(FilePath("source (1).txt"),result);Assert.Equal("原文",await File.ReadAllTextAsync(source));}
 [Fact]public async Task BatchIsolatesFailureAndDoesNotRepeat(){var ok=FilePath("ok.txt");var bad=FilePath("bad.json");await File.WriteAllTextAsync(ok,"汉字");await File.WriteAllTextAsync(bad,"{bad}");var history=new HistoryStore(FilePath("data"));var batch=new BatchService(text,new DocumentConverter(text),history);var options=new ConversionOptions{OutputDirectory=FilePath("out")};batch.Add([ok,bad,ok],options.OutputDirectory);Assert.Equal(2,batch.Jobs.Count);await batch.RunAsync(options);Assert.Single(batch.Jobs,j=>j.State==JobState.Succeeded);Assert.Single(batch.Jobs,j=>j.State==JobState.Failed);await batch.RunAsync(options);Assert.Single(Directory.GetFiles(options.OutputDirectory));Assert.Equal(2,(await history.QueryAsync()).Count);}
 [Fact]public async Task DocxCrossRunPreservesBold(){var source=FilePath("source.docx");using(var doc=WordprocessingDocument.Create(source,WordprocessingDocumentType.Document)){var part=doc.AddMainDocumentPart();part.Document=new W.Document(new W.Body(new W.Paragraph(new W.Run(new W.RunProperties(new W.Bold()),new W.Text("汉")),new W.Run(new W.Text("字")))));}
  var dst=FilePath("out.docx");await new DocumentConverter(text).ConvertAsync(source,dst,new(),default);using var output=WordprocessingDocument.Open(dst,false);Assert.Equal("漢字",output.MainDocumentPart!.Document.InnerText);Assert.Single(output.MainDocumentPart.Document.Descendants<W.Bold>());Assert.Equal(2,output.MainDocumentPart.Document.Descendants<W.Run>().Count());}
 [Fact]public async Task HistoryRoundTripAndBackup(){var history=new HistoryStore(FilePath("db"));var record=new HistoryRecord(Guid.NewGuid(),Guid.NewGuid(),DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,"s2t","[]",JobState.Succeeded,"secret.txt","out.txt",null);await history.SaveAsync(record);var json=await history.ExportJsonAsync(false);Assert.DoesNotContain("secret.txt",json);await history.ImportAsync(json,false);Assert.Single(await history.QueryAsync());await Assert.ThrowsAsync<InvalidOperationException>(()=>history.ImportAsync(json,true));await history.ImportAsync(json,true,true);Assert.Single(Directory.GetFiles(FilePath("db"),"*.bak"));Assert.Null((await history.QueryAsync())[0].SourcePath);}
 [Fact]public async Task InvalidHistoryDoesNotDeleteExisting(){var history=new HistoryStore(FilePath("db"));await history.SaveAsync(new(Guid.NewGuid(),Guid.NewGuid(),DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,"s2t","[]",JobState.Failed,null,null,null));await Assert.ThrowsAsync<InvalidDataException>(()=>history.ImportAsync("{\"schema_version\":99,\"records\":[]}",true,true));Assert.Single(await history.QueryAsync());}
 [Fact]public async Task CsvHistoryUsesBomAndNeutralizesFormula(){var history=new HistoryStore(FilePath("db"));await history.SaveAsync(new(Guid.NewGuid(),Guid.NewGuid(),DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,"s2t","[]",JobState.Succeeded,"=1+1",null,null));var path=FilePath("history.csv");await history.ExportCsvAsync(path,true);var data=await File.ReadAllBytesAsync(path);Assert.Equal(new byte[]{239,187,191},data[..3]);Assert.Contains("\"'=1+1\"",Encoding.UTF8.GetString(data));}
 [Fact]public async Task DisabledFormatIsSkippedAndRecorded(){var path=FilePath("sample.json");await File.WriteAllTextAsync(path,"{\"text\":\"汉字\"}");var history=new HistoryStore(FilePath("db"));var batch=new BatchService(text,new DocumentConverter(text),history);var options=new ConversionOptions{OutputDirectory=FilePath("out"),Formats=["txt"]};batch.Add([path],options.OutputDirectory);await batch.RunAsync(options);Assert.Equal(JobState.Skipped,batch.Jobs.Single().State);Assert.Equal(JobState.Skipped,(await history.QueryAsync()).Single().State);Assert.False(Directory.Exists(options.OutputDirectory));}
 [Fact]public void PreviewDoesNotSplitTextElements(){var text=string.Concat(Enumerable.Repeat("汉😀e\u0301",4000));var sample=PreviewService.Sample(text);Assert.DoesNotContain('\uFFFD',sample);Assert.Equal("短文",PreviewService.Sample("短文"));}
 [Fact]public async Task EpubWithoutValidatorFailsClosed(){var source=FilePath("source.epub");await File.WriteAllTextAsync(source,"invalid");await Assert.ThrowsAsync<InvalidDataException>(()=>new DocumentConverter(text).ConvertAsync(source,FilePath("out.epub"),new(),default));Assert.False(File.Exists(FilePath("out.epub")));}
 public void Dispose(){Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();Directory.Delete(dir,true);}
}
